<!doctype html><html lang="<?=$fa?'fa':'en'?>" dir="<?=$fa?'rtl':'ltr'?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>bonYe</title><style>body{font-family:Tahoma,sans-serif;background:#f7f5ee;color:#252522;margin:0;padding:24px}main{max-width:540px;margin:5vh auto;background:white;border-radius:16px;padding:28px;border:1px solid #e6e3d9}button{border:0;border-radius:8px;background:#294c36;color:white;padding:14px 20px;margin:8px 0;cursor:pointer}.secondary{background:#777}.error{color:#9d2020}p{line-height:1.9}</style></head><body><main><h1><?=esc_html(bywp_admin_label('ادامه خرید از اپ بنیه','Continue from the bonYe app'))?></h1>
