<?php if($claim):$selection=bywp_checkout_product($claim);?><p><?=esc_html(bywp_admin_label('حساب: ','Account: ').$claim['name'].' · '.substr($claim['mobile'],0,4).'•••'.substr($claim['mobile'],-4))?></p><p><?=esc_html($selection['product']->get_name())?> × <?=(int)$claim['quantity']?></p><p><?=esc_html(bywp_admin_label('این کالا به سبد فعلی افزوده می‌شود؛ اقلام قبلی حذف نمی‌شوند. تعداد و قیمت نهایی را در پرداخت سایت بررسی کنید.','This item will be added to your existing cart. Existing items are retained. Review quantity and the final price at website checkout.'))?></p><form method="post"><input type="hidden" name="bonye_lang" value="<?=$fa?'fa':'en'?>"><input type="hidden" name="csrf" value="<?=esc_attr($csrf)?>"><button name="bonye_checkout_stage" value="confirm"><?=esc_html(bywp_admin_label('تأیید حساب و افزودن به سبد','Confirm account and add to cart'))?></button> <button class="secondary" name="bonye_checkout_stage" value="cancel"><?=esc_html(bywp_admin_label('انصراف','Cancel'))?></button></form>
<?php else:?><p><?=esc_html(bywp_admin_label('برای بررسی لینک خرید اپ، ادامه را بزنید. لینک منقضی را دوباره از اپ درخواست کنید.','Continue to verify the app checkout link. Request a new link in the app if it expired.'))?></p><form method="post" id="app-form" hidden><input type="hidden" name="bonye_lang" value="<?=$fa?'fa':'en'?>"><input type="hidden" name="csrf" value="<?=esc_attr($csrf)?>"><input type="hidden" name="bonye_checkout_stage" value="claim"><input type="hidden" name="ticket" id="app-ticket"><button><?=esc_html(bywp_admin_label('بررسی لینک خرید','Verify checkout link'))?></button></form><script>const t=new URLSearchParams(location.hash.slice(1)).get('bonye_checkout');history.replaceState(null,'',location.pathname+location.search);if(t&&/^[a-f0-9]{64}$/.test(t)){document.getElementById('app-ticket').value=t;document.getElementById('app-form').hidden=false;}</script><?php endif;?>
